CREATE TYPE public.app_role AS ENUM ('super_admin', 'organization_admin', 'learner');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, university_id text, UNIQUE(user_id, role), CONSTRAINT scoped_admin CHECK (role = 'super_admin' OR university_id IS NOT NULL));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.can_manage_community_university(uid uuid, university text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND (role='super_admin' OR (role='organization_admin' AND university_id=university))) $$;
CREATE FUNCTION public.can_read_community_university(uid uuid, university text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND (role='super_admin' OR university_id=university)) $$;
CREATE TABLE public.community_universities (id text PRIMARY KEY, name text NOT NULL CHECK(length(trim(name))>0));
GRANT SELECT,INSERT,UPDATE ON public.community_universities TO authenticated;
GRANT ALL ON public.community_universities TO service_role;
ALTER TABLE public.community_universities ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_universities ON public.community_universities FOR SELECT TO authenticated USING(public.can_read_community_university(auth.uid(),id));
CREATE POLICY manage_universities ON public.community_universities FOR ALL TO authenticated USING(public.can_manage_community_university(auth.uid(),id)) WITH CHECK(public.can_manage_community_university(auth.uid(),id));
CREATE TABLE public.community_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), university_id text NOT NULL REFERENCES public.community_universities(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX community_category_names ON public.community_categories(university_id,lower(trim(name)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.community_categories TO authenticated;
GRANT ALL ON public.community_categories TO service_role;
ALTER TABLE public.community_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_categories ON public.community_categories FOR SELECT TO authenticated USING(public.can_manage_community_university(auth.uid(),university_id) OR (active AND public.can_read_community_university(auth.uid(),university_id)));
CREATE POLICY manage_categories ON public.community_categories FOR ALL TO authenticated USING(public.can_manage_community_university(auth.uid(),university_id)) WITH CHECK(public.can_manage_community_university(auth.uid(),university_id));
CREATE TABLE public.communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), university_id text NOT NULL REFERENCES public.community_universities(id), category_id uuid REFERENCES public.community_categories(id) ON DELETE RESTRICT, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150), description text NOT NULL DEFAULT '', thumbnail text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX community_names ON public.communities(university_id,lower(trim(name)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.communities TO authenticated;
GRANT ALL ON public.communities TO service_role;
ALTER TABLE public.communities ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_communities ON public.communities FOR SELECT TO authenticated USING(public.can_manage_community_university(auth.uid(),university_id) OR (active AND public.can_read_community_university(auth.uid(),university_id)));
CREATE POLICY manage_communities ON public.communities FOR ALL TO authenticated USING(public.can_manage_community_university(auth.uid(),university_id)) WITH CHECK(public.can_manage_community_university(auth.uid(),university_id));
CREATE TABLE public.community_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL, display_name text NOT NULL CHECK(length(trim(display_name))>0), joined_at timestamptz NOT NULL DEFAULT now(), UNIQUE(community_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.community_members TO authenticated;
GRANT ALL ON public.community_members TO service_role;
ALTER TABLE public.community_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_members ON public.community_members FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND public.can_manage_community_university(auth.uid(),c.university_id)) OR (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND c.active)));
CREATE POLICY manage_members ON public.community_members FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND public.can_manage_community_university(auth.uid(),c.university_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND public.can_manage_community_university(auth.uid(),c.university_id)));
CREATE TABLE public.community_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, category_id uuid NOT NULL REFERENCES public.community_categories(id) ON DELETE RESTRICT, author_id uuid NOT NULL, author_name text NOT NULL, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), body text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.community_posts TO authenticated;
GRANT ALL ON public.community_posts TO service_role;
ALTER TABLE public.community_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_posts ON public.community_posts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id));
CREATE POLICY create_posts ON public.community_posts FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND c.active AND EXISTS(SELECT 1 FROM public.community_categories cat WHERE cat.id=category_id AND cat.active AND cat.university_id=c.university_id)) AND (EXISTS(SELECT 1 FROM public.community_members m WHERE m.community_id=community_posts.community_id AND m.user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND public.can_manage_community_university(auth.uid(),c.university_id))));
CREATE POLICY delete_posts ON public.community_posts FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.communities c WHERE c.id=community_id AND public.can_manage_community_university(auth.uid(),c.university_id)));
CREATE FUNCTION public.validate_community_relations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE university text; BEGIN IF TG_TABLE_NAME='communities' THEN university:=NEW.university_id; ELSE SELECT university_id INTO university FROM public.communities WHERE id=NEW.community_id; END IF; IF NEW.category_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.community_categories WHERE id=NEW.category_id AND university_id=university AND (active OR (TG_OP='UPDATE' AND NEW.category_id=OLD.category_id))) THEN RAISE EXCEPTION 'Select an active category from the same university'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_community_category BEFORE INSERT OR UPDATE ON public.communities FOR EACH ROW EXECUTE FUNCTION public.validate_community_relations();
CREATE TRIGGER validate_post_category BEFORE INSERT OR UPDATE ON public.community_posts FOR EACH ROW EXECUTE FUNCTION public.validate_community_relations();
CREATE FUNCTION public.community_member_candidates(university text) RETURNS TABLE(user_id uuid,display_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.user_id,coalesce(nullif(u.raw_user_meta_data->>'name',''),'Learner '||left(r.user_id::text,8)) FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.role='learner' AND r.university_id=university AND public.can_manage_community_university(auth.uid(),university) $$;
CREATE FUNCTION public.validate_community_member() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.communities c JOIN public.user_roles r ON r.university_id=c.university_id AND r.user_id=NEW.user_id AND r.role='learner' WHERE c.id=NEW.community_id) THEN RAISE EXCEPTION 'Learner must belong to this university'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_member BEFORE INSERT ON public.community_members FOR EACH ROW EXECUTE FUNCTION public.validate_community_member();
CREATE INDEX community_posts_community ON public.community_posts(community_id);
CREATE INDEX community_members_community ON public.community_members(community_id);
CREATE INDEX communities_university ON public.communities(university_id);